import json
from fractions import Fraction as F

# Put z = exp(s). Represent exact Laurent polynomials in z by
# dictionaries {exponent: coefficient}. Write x=tau*X, y=tau*Y,
# u=tau**2*U, so polynomial identities also hold at tau=0.
def poly(terms):
    return {k: F(v) for k, v in terms.items() if v != 0}

def add(a, b):
    result = dict(a)
    for k, v in b.items():
        result[k] = result.get(k, F(0)) + v
    return poly(result)

def scale(a, c):
    return poly({k: c * v for k, v in a.items()})

def mul(a, b):
    result = {}
    for i, v in a.items():
        for j, w in b.items():
            result[i + j] = result.get(i + j, F(0)) + v * w
    return poly(result)

def derivative(a):
    # d(z**k)/ds = k*z**k.
    return poly({k: k * v for k, v in a.items()})

def initial(a):
    return sum(a.values(), F(0))  # s=0 gives z=1.

options = [
    (
        poly({1: 3, 0: -3}),
        poly({-1: F(1, 2), 0: F(1, 2)}),
        poly({-2: 1}),
    ),
    (
        poly({1: 2, 0: -2}),
        poly({2: 2, 0: -1}),
        poly({0: F(1, 2), -2: F(1, 2)}),
    ),
    (
        poly({1: 2, 0: -2}),
        poly({1: F(1, 2), 0: F(1, 2)}),
        poly({2: 1}),
    ),
    (
        poly({-1: 1, 0: -1}),
        poly({-1: -2, 0: 3}),
        poly({-2: 2, 0: -1}),
    ),
]

# For H=p*q-u, Charpit gives:
# x'=q, y'=p, u'=2*p*q, p'=p, q'=q.
# Initial compatibility gives q(0)=2*tau and
# p(0)*q(0)=tau**2, hence p(0)=tau/2 for tau!=0,
# with the same smooth continuation at tau=0.
# Thus P=p/tau=(1/2)*exp(s), Q=q/tau=2*exp(s).
expected_p = poly({1: F(1, 2)})
expected_q = poly({1: 2})

valid = []
checks = []
for number, (x, y, u) in enumerate(options, 1):
    q = derivative(x)
    p = derivative(y)
    pq = mul(p, q)

    tests = {
        "initial_curve": (initial(x), initial(y), initial(u))
                         == (F(0), F(1), F(1)),
        "initial_gradient_and_Charpit": (
            p == expected_p and q == expected_q
            and derivative(p) == p and derivative(q) == q
        ),
        "PDE": pq == u,
        "u_evolution": derivative(u) == scale(pq, 2),
    }
    if all(tests.values()):
        valid.append(number)
    checks.append({
        "option": number,
        "failed": [name for name, passed in tests.items() if not passed],
    })

if len(valid) != 1:
    print("UNSUPPORTED")
else:
    print(json.dumps({
        "final_answer": "Option " + str(valid[0]),
        "evidence": {
            "Charpit": "x'=q, y'=p, u'=2pq, p'=p, q'=q",
            "initial_gradient": "p(0)=tau/2, q(0)=2tau (smooth at tau=0)",
            "exact_checks": checks,
        },
    }, separators=(",", ":")))
