import json
from functools import lru_cache
from itertools import product

# ":" represents vowel length; phonetic labialization is expanded to "w".
givens = [
    ("tmi’gn", "dəmi:gən"),
    ("an’stawteg", "anəstawtek"),
    ("gjiansale’wit", "əkciansale:wit"),
    ("mgumie’jo’tlatl", "əmkumie:jo:dəladəl"),
    ("amqwanji’j", "amxwanci:c"),
    ("e’jnt", "e:jənt"),
    ("tplutaqan", "ətpəludaɣan"),
    ("ge’gwising", "ge:gwisink"),
    ("lnu’sgw", "lənu:skw"),
    ("g’p’ta’q", "gəbəda:x"),
    ("epsaqtejg", "epsaxteck"),
]

def orth_tokens(word):
    result = []
    for char in word.replace("’", "'"):
        if char == "'" and result and result[-1] in "aeiou":
            result[-1] += ":"
        else:
            result.append(char)
    return tuple(result)

def sound_tokens(text):
    result = []
    for char in text:
        if char == ":":
            result[-1] += ":"
        else:
            result.append(char)
    return tuple(result)

# Segment correspondences, with voicing alternatives.
correspondence = {
    "t": {"t", "d"}, "p": {"p", "b"}, "g": {"g", "k"},
    "j": {"j", "c"}, "q": {"x", "ɣ"}, "'": {"ə"},
}
for char in "aeioumnlsw":
    correspondence[char] = {char}
for char in "aeiou":
    correspondence[char + ":"] = {char + ":"}

def align(orth, sounds, insertion_allowed=lambda position, orth: True):
    @lru_cache(None)
    def visit(i, j):
        if i == len(orth) and j == len(sounds):
            return ((),)
        results = []
        if i < len(orth) and j < len(sounds):
            if sounds[j] in correspondence.get(orth[i], set()):
                for tail in visit(i + 1, j + 1):
                    results.append((("match", i, sounds[j]),) + tail)
        if j < len(sounds) and sounds[j] == "ə":
            if insertion_allowed(i, orth):
                for tail in visit(i, j + 1):
                    results.append((("insert", i, "ə"),) + tail)
        return tuple(results)
    return visit(0, 0)

observed = {}
inserted_before = set()
initial_insertion = False
training_alignments = []

for spelling, transcription in givens:
    orth = orth_tokens(spelling)
    sounds = sound_tokens(transcription)
    paths = align(orth, sounds)
    if len(paths) != 1:
        print("UNSUPPORTED")
        raise SystemExit
    training_alignments.append((orth, sounds))
    for operation, position, sound in paths[0]:
        if operation == "match":
            observed.setdefault(sound, set()).add(orth[position])
        elif position == 0:
            initial_insertion = True
        elif position < len(orth):
            inserted_before.add(orth[position])
        else:
            print("UNSUPPORTED")
            raise SystemExit

# Unwritten schwas occur initially or before the sonorants learned
# from the examples. Schwas between obstruents are explicitly written.
def allowed(position, orth):
    return (
        (position == 0 and initial_insertion)
        or (position < len(orth) and orth[position] in inserted_before)
    )

if not all(align(o, s, allowed) for o, s in training_alignments):
    print("UNSUPPORTED")
    raise SystemExit

target = sound_tokens("alaptək")
choices = []
for sound in target:
    alternatives = set(observed.get(sound, ()))
    if sound == "ə":
        alternatives.add("")  # Test an unwritten, inserted schwa too.
    if not alternatives:
        print("UNSUPPORTED")
        raise SystemExit
    choices.append(sorted(alternatives))

accepted = set()
tested = 0
for parts in product(*choices):
    spelling = "".join(parts)
    tested += 1
    if align(orth_tokens(spelling), target, allowed):
        accepted.add(spelling)

if len(accepted) != 1:
    print("UNSUPPORTED")
else:
    answer = next(iter(accepted)).replace("'", "’")
    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "unwritten_schwa_before": sorted(inserted_before),
            "candidates_tested": tested,
            "unique_valid_spelling": answer,
            "reason": "The schwa before g must be written with an apostrophe."
        }
    }, ensure_ascii=False))
