import json
import unicodedata

givens = [
    ("dikiʔ", "takiʔ"),
    ("dilah", "talàh"),
    ("paley", "paley"),
    ("mata", "mɨta"),
    ("batuk", "patuʔ"),
    ("bəsey", "pathey"),
]

def unaccent(text):
    return "".join(
        c for c in unicodedata.normalize("NFD", text)
        if not unicodedata.combining(c)
    )

# Infer the reduced first syllable of roots beginning with *d.
d_prefixes = {
    unaccent(cham[:2])
    for proto, cham in givens
    if proto.startswith("d")
}

# Infer unchanged *p from the directly attested correspondence in *paley.
p_onsets = {
    cham[0]
    for proto, cham in givens
    if proto.startswith("p")
}

# Infer final short *a after a voiceless stop from *mata > mɨta.
# The other voiceless-final-syllable examples likewise lack a grave accent.
a_endings = {
    cham[-1]
    for proto, cham in givens
    if proto.endswith("ta")
}

if len(d_prefixes) != 1 or len(p_onsets) != 1 or len(a_endings) != 1:
    print("UNSUPPORTED")
else:
    prefix = next(iter(d_prefixes))
    onset = next(iter(p_onsets))
    vowel = next(iter(a_endings))
    target = "dəpa"
    answer = prefix + onset + vowel

    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "target": "*" + target,
            "initial_d_and_reduced_vowel": {
                "examples": ["*dikiʔ → takiʔ", "*dilah → talàh"],
                "computed": prefix
            },
            "p_correspondence": {
                "example": "*paley → paley",
                "computed": onset
            },
            "final_short_a_after_voiceless_stop": {
                "example": "*mata → mɨta",
                "computed": vowel
            },
            "composition": [prefix, onset, vowel]
        }
    }, ensure_ascii=False, separators=(",", ":")))
