import re
import math

# All geometric tolerances are substantially smaller than the drawn features,
# but allow the stated rounding of coordinates to five decimal places.
EPS = 0.0001
path = """
M 24.38698,-19.9365 L 29.3405,-17.62663
M 0.0,7.0 L 0.0,5.46
M 10.35209,0.0 L 10.35209,-7.0986
M 20.49493,-28.84999 L 17.75636,-22.97711
M 20.49493,-21.75139 L 24.38698,-19.9365
M 18.29129,-17.02568 L 20.49493,-21.75139
M 17.75636,-22.97711 L 15.16487,-17.41963
M 10.35209,-7.0986 L 0.0,-7.0986
M 22.10067,8.68911 L 19.34832,10.61633
M 2.5205,-5.64339 L 6.14757,-3.5493
M 10.35209,-4.68508 L 10.35209,0.0
M 10.35209,-7.0986 L 10.35209,-4.68508
M 20.49493,-25.44266 L 20.49493,-28.84999
M 0.0,-7.0986 L 2.5205,-5.64339
M 6.14757,-3.5493 L 2.33608,-1.34873
M 24.85302,6.76189 L 22.10067,8.68911
M 15.93065,-11.96326 L 17.25429,-14.80182
M 20.49493,-21.75139 L 20.49493,-25.44266
M 19.34832,10.61633 L 17.21983,12.10671 L 11.74658,15.93912
M 10.35209,1.96 L 10.35209,3.3712
M 0.0,5.46 L 0.0,0.0
M 4.03732,0.0 L 10.35209,0.0
M 10.35209,7.0 L 7.55703,7.0
M 10.35209,0.0 L 15.93065,-11.96326
M 10.35209,3.3712 L 10.35209,7.0
M 2.33608,-1.34873 L 0.0,0.0
M 34.99586,-14.98949 L 24.85302,6.76189
M 15.16487,-17.41963 L 10.35209,-7.0986
M 11.74658,15.93912 L 11.17484,9.40408
M 0.0,0.0 L 4.03732,0.0
M 11.17484,9.40408 L 10.79637,5.0782
M 29.3405,-17.62663 L 34.99586,-14.98949
M 10.35209,0.0 L 10.35209,1.96
M 10.79637,5.0782 L 10.35209,0.0
M 7.55703,7.0 L 0.0,7.0
M 17.25429,-14.80182 L 18.29129,-17.02568
"""

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]

def length(a):
    return math.hypot(*a)

def on_segment(p, a, b):
    v, w = sub(b, a), sub(p, a)
    return (abs(cross(v, w)) <= EPS * length(v)
            and -EPS * length(v) <= dot(w, v)
            <= dot(v, v) + EPS * length(v))

segments = []
previous = None
for command, x, y in re.findall(
        r"([ML])\s*([-+\d.]+),([-+\d.]+)", path):
    point = (float(x), float(y))
    if command == "L":
        segments.append((previous, point))
    previous = point

# Construct the complete planar arrangement, merging overlapping strokes.
points = []
def intern(p):
    for i, q in enumerate(points):
        if length(sub(p, q)) < EPS:
            return i
    points.append(p)
    return len(points) - 1

for a, b in segments:
    intern(a)
    intern(b)

for i, (a, b) in enumerate(segments):
    u = sub(b, a)
    for c, d in segments[i + 1:]:
        v = sub(d, c)
        denominator = cross(u, v)
        if abs(denominator) <= EPS * length(u) * length(v):
            continue
        t = cross(sub(c, a), v) / denominator
        s = cross(sub(c, a), u) / denominator
        if 0 <= t <= 1 and 0 <= s <= 1:
            intern((a[0] + t * u[0], a[1] + t * u[1]))

edges = set()
for a, b in segments:
    v = sub(b, a)
    cuts = [i for i, p in enumerate(points) if on_segment(p, a, b)]
    cuts.sort(key=lambda i: dot(sub(points[i], a), v))
    for i, j in zip(cuts, cuts[1:]):
        if i != j:
            edges.add(tuple(sorted((i, j))))

adj = {i: set() for i in range(len(points))}
for a, b in edges:
    adj[a].add(b)
    adj[b].add(a)

# Exhaustively enumerate simple cycles. A cycle starts at its minimum vertex;
# the orientation test removes the reverse duplicate.
cycles = []
def search(start, route, used):
    for v in sorted(adj[route[-1]]):
        if v == start:
            if len(route) >= 3 and route[1] < route[-1]:
                cycles.append(tuple(route))
        elif v > start and v not in used:
            search(start, route + [v], used | {v})

for start in adj:
    search(start, [start], {start})

def simplify(poly):
    poly = list(poly)
    changed = True
    while changed and len(poly) >= 3:
        changed = False
        for i in range(len(poly)):
            a, b, c = poly[i - 1], poly[i], poly[(i + 1) % len(poly)]
            if on_segment(b, a, c):
                del poly[i]
                changed = True
                break
    return poly

def strictly_inside(p, poly):
    if any(on_segment(p, a, b)
           for a, b in zip(poly, poly[1:] + poly[:1])):
        return False
    inside = False
    for a, b in zip(poly, poly[1:] + poly[:1]):
        if (a[1] > p[1]) != (b[1] > p[1]):
            x = a[0] + (p[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            if p[0] < x:
                inside = not inside
    return inside

def parallel(u, v):
    return abs(cross(u, v)) <= EPS * length(u) * length(v)

def perpendicular(u, v):
    return abs(dot(u, v)) <= EPS * length(u) * length(v)

def classify(poly):
    n = len(poly)
    vectors = [sub(poly[(i + 1) % n], poly[i]) for i in range(n)]
    turns = [cross(vectors[i - 1], vectors[i]) for i in range(n)]
    convex = all(t > 0 for t in turns) or all(t < 0 for t in turns)
    right = [perpendicular(vectors[i - 1], vectors[i]) for i in range(n)]
    lengths = list(map(length, vectors))
    equal_sides = max(lengths) - min(lengths) <= EPS * max(lengths)
    angles = [
        math.atan2(abs(cross(vectors[i - 1], vectors[i])),
                   dot(vectors[i - 1], vectors[i]))
        for i in range(n)
    ]
    regular = convex and equal_sides and max(angles) - min(angles) <= EPS
    if n == 3:
        return {4 if any(right) else 3}
    if n == 4:
        opposite = [parallel(vectors[0], vectors[2]),
                    parallel(vectors[1], vectors[3])]
        if all(right):
            return {2 if equal_sides else 1}
        if all(opposite):
            return {5}
        if convex and sum(opposite) == 1:
            return {6}
    if n == 5:
        return {9 if regular else (7 if convex else 8)}
    if n == 6 and regular:
        return {10}
    return set()

found = set()
witnesses = {}
for cycle in cycles:
    poly = simplify([points[i] for i in cycle])
    kinds = classify(poly)
    if not kinds:
        continue
    # For categories requiring no diagonals, reject every cycle enclosing
    # another drawn edge. Arrangement edges cannot cross the cycle boundary.
    has_internal_line = any(
        strictly_inside(((points[a][0] + points[b][0]) / 2,
                         (points[a][1] + points[b][1]) / 2), poly)
        for a, b in edges
    )
    if has_internal_line:
        kinds &= {3, 4}
    for kind in kinds:
        found.add(kind)
        witnesses.setdefault(kind, poly)

options = {
    "A": {1, 7, 3}, "B": {1, 8}, "C": {7, 9}, "D": {5},
    "E": {1, 5, 7, 8}, "F": {1, 5, 7, 8, 4, 6},
    "G": {7, 8, 2, 10}, "H": {1, 8, 9}, "I": {5, 3},
    "J": {1}, "K": {7, 8}, "L": {5, 8}, "M": {5, 2},
    "N": {1, 8, 2, 4, 9}, "O": {1, 5, 7, 8, 10},
    "P": {1, 7, 8, 6},
}
print("Method: exhaustive planar-graph simple-cycle enumeration;"
      " five-decimal rounding tolerance =", EPS)
print("Simple cycles examined:", len(cycles))
print("Computed shape numbers:", sorted(found))
for kind in sorted(witnesses):
    print("Shape", kind, "vertices:", witnesses[kind])
print("Matching options:", [k for k, v in options.items() if v == found])
print("Submitted E contains:", sorted(options["E"]))
print("CHECK PASS" if found == options["E"] else "CHECK FAIL")
