# "Do not eat out-of-season vegetables" prohibits eating them.
# A prohibition alone does not assert that such vegetables existed.
names = (
    "demanding",
    "seasonal_in_confucius_era",
    "out_of_season_in_confucius_era",
    "seasonal_available_now",
    "out_of_season_available_now",
    "diet_shapes_mind",
    "eats_out_of_season",
)

models = []
for values in itertools.product((False, True), repeat=len(names)):
    m = dict(zip(names, values))
    if m["eats_out_of_season"]:
        continue
    models.append(m)

def statements(m):
    return {
        "A": m["demanding"],
        "B": (
            m["seasonal_in_confucius_era"]
            and m["out_of_season_in_confucius_era"]
        ),
        "C": (
            m["seasonal_available_now"]
            and m["out_of_season_available_now"]
        ),
        "unlabelled": m["diet_shapes_mind"],
    }

countermodel_counts = {
    label: sum(not statements(m)[label] for m in models)
    for label in statements(models[0])
}
necessary = [
    label for label, count in countermodel_counts.items() if count == 0
]

result = {
    "final_answer": necessary[0] if len(necessary) == 1 else "UNSUPPORTED",
    "evidence": {
        "models_checked": len(models),
        "countermodels": countermodel_counts,
        "reason": (
            "Under the explicit prohibition, no listed statement is necessary. "
            "In particular, a prohibition has no existential import; B requires "
            "an additional presupposition about historical availability."
        ),
    },
}
print(json.dumps(result, separators=(",", ":")))
