            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
    if isinstance(node, ast.BoolOp):
        # Evaluate every operand, rather than relying on short-circuiting.
        values = [bool(compute(value)) for value in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
    if isinstance(node, ast.Compare):
        left = compute(node.left)
        results = []
        for op, other in zip(node.ops, node.comparators):
            right = compute(other)
            if isinstance(op, ast.Gt):
                results.append(left > right)
            elif isinstance(op, ast.LtE):
                results.append(left <= right)
            else:
                raise ValueError("Unsupported comparison")
            left = right
        return all(results)
    if isinstance(node, ast.Call):
        if (isinstance(node.func, ast.Name)
                and node.func.id in ("max", "min")
                and not node.keywords):
            values = [compute(arg) for arg in node.args]
            return (max if node.func.id == "max" else min)(values)
    raise ValueError("Unsupported syntax")

try:
    values = {}
    for label, source in expressions.items():
        for sentence, truth in facts.items():
            source = source.replace(sentence, str(truth))
        source = source.replace("is less than or equal to", "<=")
        source = source.replace("is greater than", ">")
        value = compute(ast.parse(source, mode="eval"))
        if type(value) is not bool:
            raise ValueError("Expression is not Boolean")
        values[label] = value

    winners = [label for label, value in values.items() if value]
    answer = winners[0] if len(winners) == 1 else "UNSUPPORTED"
    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "values": values,
            "arithmetic": "exact rational",
            "true_count": len(winners)
        }
    }, separators=(",", ":")))
except Exception:
