import json
from fractions import Fraction as F

S, Q = F(9), F(14)
D = S * S - 3 * Q

# Exact arithmetic in Q(sqrt(D)), represented by (a, b).
def scalar(x):
    return (F(x), F(0))

def add(u, v):
    return (u[0] + v[0], u[1] + v[1])

def neg(u):
    return (-u[0], -u[1])

def sub(u, v):
    return add(u, neg(v))

def mul(u, v):
    return (u[0] * v[0] + D * u[1] * v[1],
            u[0] * v[1] + u[1] * v[0])

def div(u, v):
    norm = v[0] * v[0] - D * v[1] * v[1]
    assert norm != 0
    w = mul(u, (v[0], -v[1]))
    return (w[0] / norm, w[1] / norm)

def sign(u):
    a, b = u
    if b == 0:
        return (a > 0) - (a < 0)
    if a == 0:
        return (b > 0) - (b < 0)
    if (a > 0) == (b > 0):
        return 1 if a > 0 else -1
    delta = a * a - D * b * b
    return ((delta > 0) - (delta < 0)) * (1 if a > 0 else -1)

def fmt(u):
    a, b = u
    if not b:
        return str(a)
    radical = ("sqrt(%s)" % D) if abs(b) == 1 else (
        "%s*sqrt(%s)" % (abs(b), D))
    if not a:
        return ("-" if b < 0 else "") + radical
    return "%s %s %s" % (a, "+" if b > 0 else "-", radical)

# At an interior extremum of xyz, two coordinates must coincide.
# With x=y=a, the constraints give 3a^2-2Sa+Q=0.
candidates = []
feasible = []
for direction in (-1, 1):
    a = (S / 3, F(direction, 3))
    z = sub(scalar(S), mul(scalar(2), a))
    positive = sign(a) > 0 and sign(z) > 0
    candidates.append({
        "repeated_coordinate": fmt(a),
        "third_coordinate": fmt(z),
        "positive": positive
    })
    if positive:
        assert add(mul(a, a), mul(scalar(2), mul(a, z))) == scalar(Q)
        feasible.append(mul(mul(a, a), z))

assert len(feasible) == 1
r = feasible[0]
assert sign(r) > 0
assert sign(sub(scalar(S * Q), r)) > 0

# The original objective equals
# 2S - 2(Q^2 + S*r)/(S*Q-r), where r=xyz.
answer = sub(
    scalar(2 * S),
    div(mul(scalar(2), add(scalar(Q * Q), mul(scalar(S), r))),
        sub(scalar(S * Q), r))
)
derivative_numerator = -2 * Q * (S * S + Q)

print(json.dumps({
    "final_answer": fmt(answer),
    "evidence": {
        "objective_in_r": "18 - 2*(196 + 9*r)/(126 - r), r=xyz",
        "derivative_numerator": str(derivative_numerator),
        "two_equal_candidates": candidates,
        "maximum_xyz": fmt(r),
        "attainment": "Permutations of the positive candidate.",
        "global_argument": (
            "The nonnegative constraint set is compact. Boundary products "
            "are zero, while the positive candidate has positive product, "
            "so a product maximum is interior. The constraint gradients "
            "are independent since all-equal coordinates violate xy+yz+zx=14. "
            "Lagrange equations force two coordinates equal: if all were "
            "distinct, subtracting the equations would force all coordinates "
            "equal. The enumeration above leaves exactly one positive "
            "candidate. The objective strictly decreases with xyz."
        )
    }
}, separators=(",", ":")))
