from fractions import Fraction as F

# Exact arithmetic in Q(sqrt(39)): (a,b) represents a+b*sqrt(39).
def add(u, v):
    return (u[0] + v[0], u[1] + v[1])

def neg(u):
    return (-u[0], -u[1])

def sub(u, v):
    return add(u, neg(v))

def mul(u, v):
    return (u[0]*v[0] + 39*u[1]*v[1],
            u[0]*v[1] + u[1]*v[0])

def div(u, v):
    norm = v[0]*v[0] - 39*v[1]*v[1]
    assert norm != 0
    w = mul(u, (v[0], -v[1]))
    return (w[0]/norm, w[1]/norm)

def rat(n):
    return (F(n), F(0))

def positive(u):
    a, b = u
    if b == 0:
        return a > 0
    if b > 0:
        return a >= 0 or 39*b*b > a*a
    return a > 0 and a*a > 39*b*b

def fmt(u):
    a, b = u
    if b == 0:
        return str(a)
    return f"({a}) {'+' if b > 0 else '-'} ({abs(b)})*sqrt(39)"

# Sparse polynomial arithmetic, used to check the identities exactly.
ZERO = {}
ONE = {(0, 0, 0): F(1)}

def padd(*polys):
    out = {}
    for poly in polys:
        for e, c in poly.items():
            out[e] = out.get(e, F(0)) + c
    return {e: c for e, c in out.items() if c}

def scale(poly, c):
    return {e: c*v for e, v in poly.items() if c*v}

def pmul(a, b):
    out = {}
    for e, c in a.items():
        for f, d in b.items():
            g = tuple(e[i] + f[i] for i in range(3))
            out[g] = out.get(g, F(0)) + c*d
    return {e: c for e, c in out.items() if c}

def power(a, n):
    out = ONE
    for _ in range(n):
        out = pmul(out, a)
    return out

x = {(1, 0, 0): F(1)}
y = {(0, 1, 0): F(1)}
z = {(0, 0, 1): F(1)}
p = padd(x, y, z)
q = padd(pmul(x, y), pmul(y, z), pmul(z, x))
r = pmul(pmul(x, y), z)

xy, xz, yz = padd(x, y), padd(x, z), padd(y, z)
den = pmul(pmul(xy, xz), yz)
num = padd(
    pmul(padd(power(x, 2), power(y, 2)), pmul(xz, yz)),
    pmul(padd(power(x, 2), power(z, 2)), pmul(xy, yz)),
    pmul(padd(power(y, 2), power(z, 2)), pmul(xy, xz)),
)

assert den == padd(pmul(p, q), scale(r, -1))
assert num == padd(
    scale(pmul(p, den), 2),
    scale(padd(power(q, 2), pmul(p, r)), -2)
)

discriminant = padd(
    pmul(power(p, 2), power(q, 2)),
    scale(power(q, 3), -4),
    scale(pmul(power(p, 3), r), -4),
    scale(power(r, 2), -27),
    scale(pmul(pmul(p, q), r), 18),
)
squared_differences = pmul(
    pmul(power(padd(x, scale(y, -1)), 2),
         power(padd(y, scale(z, -1)), 2)),
    power(padd(z, scale(x, -1)), 2),
)
assert discriminant == squared_differences

# For p=9, q=14:
# E(r) = (1876-36r)/(126-r).
# Its derivative has numerator -2660, so E is strictly decreasing.
derivative_numerator = -36*126 + 1876
assert derivative_numerator == -2660

# The verified discriminant identity gives
# 4900-648r-27r^2 = (x-y)^2(y-z)^2(z-x)^2 >= 0.
assert 9**2 * 14**2 - 4*14**3 == 4900
assert -4*9**3 + 18*9*14 == -648

rmax = (F(-12), F(26, 9))
rmin_root = (F(-12), F(-26, 9))
for root in (rmax, rmin_root):
    assert sub(sub(rat(4900), mul(rat(648), root)),
               mul(rat(27), mul(root, root))) == rat(0)
assert positive(rmax)
assert positive(neg(rmin_root))
assert positive(sub(rat(126), rmax))

# Attainment: two equal small variables and one large variable.
a = (F(3), F(-1, 3))
b = (F(3), F(2, 3))
assert positive(a) and positive(b)
assert add(add(a, a), b) == rat(9)
assert add(mul(a, a), mul(rat(2), mul(a, b))) == rat(14)
assert mul(mul(a, a), b) == rmax

minimum = div(sub(rat(1876), mul(rat(36), rmax)),
              sub(rat(126), rmax))
direct = add(a, mul(rat(2),
                   div(add(mul(a, a), mul(b, b)), add(a, b))))
assert direct == minimum

print("Exact minimum:", fmt(minimum))
print("Attained at x=y =", fmt(a), "and z =", fmt(b))
print("Global certificate: discriminant bounds xyz above; E decreases in xyz.")
print("CHECK PASS: independently computed minimum and exact attainment.")

# Also refute the submitted numerator simplification on a feasible point:
# (x,y,z) = (1, 4+sqrt(10), 4-sqrt(10)).
# Its sum is 9, pairwise-product sum is 14, and product is 6.
assert 4*4 - 10 == 6
assert 1*8 + 6 == 14
assert 4*4 > 10  # both 4 +/- sqrt(10) are positive
p0, q0, r0 = 9, 14, 6
den0 = p0*q0 - r0
actual_num = 2*p0*den0 - 2*(q0*q0 + p0*r0)
submitted_num = 2*(p0**3 - 3*p0*q0 + 3*r0) + 3*p0*r0
assert actual_num != submitted_num
print("Feasible counterexample to submitted algebra:")
print("  Actual expression =", F(actual_num, den0))
print("  Submitted simplified expression =", F(submitted_num, den0))
print("CHECK FAIL: submitted answer gives no minimum and contains false algebra.")
