# Each mask specifies which membership classes are inhabited:
# neither A nor B, A only, B only, both A and B.
models = range(16)

def some_a_not_b(mask):
    return bool(mask & (1 << 1))

def some_b_not_a(mask):
    return bool(mask & (1 << 2))

def not_all_a_are_b(mask):
    return not all(
        not (mask & (1 << cell)) or cell == 3
        for cell in (1, 3)
    )

def not_all_b_are_a(mask):
    return not all(
        not (mask & (1 << cell)) or cell == 3
        for cell in (2, 3)
    )

# A, C and D reverse the two categories, as the original does.
# B merely restates "some A are not B" as "not all A are B".
conclusions = {
    "original": not_all_b_are_a,
    "A": some_b_not_a,
    "B": not_all_a_are_b,
    "C": some_b_not_a,
    "D": not_all_b_are_a,
}

results = {}
for label, conclusion in conclusions.items():
    countermodels = [
        mask for mask in models
        if some_a_not_b(mask) and not conclusion(mask)
    ]
    results[label] = {
        "valid": not countermodels,
        "countermodel_masks": countermodels,
    }

original_signature = tuple(
    conclusion(mask)
    for mask in models
    for conclusion in (conclusions["original"],)
)
different = [
    label for label in "ABCD"
    if tuple(conclusions[label](mask) for mask in models)
    != original_signature
]

settled = (
    len(different) == 1
    and results[different[0]]["valid"]
    and not results["original"]["valid"]
)

