M -15.59808,14.80251 L -15.59808,13.48251 L -15.59808,8.80251
M 0.0,14.80251 L 9.07607,14.80251"""

def sub(a, b):
    return a[0] - b[0], a[1] - b[1]

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]

def on_segment(p, a, b):
    return (cross(sub(p, a), sub(b, a)) == 0
            and min(a[0], b[0]) <= p[0] <= max(a[0], b[0])
            and min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))

segments = []
previous = None
for command, x, y in re.findall(
        r"([ML])\s+(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)", svg):
    point = (F(x), F(y))
    if command == "L":
        segments.append((previous, point))
    previous = point

# Exact planar subdivision, including overlapping and repeated segments.
cuts = [set(s) for s in segments]
for i, j in combinations(range(len(segments)), 2):
    a, b = segments[i]
    c, d = segments[j]
    r, s = sub(b, a), sub(d, c)
    denominator = cross(r, s)
    if denominator:
        t = cross(sub(c, a), s) / denominator
        u = cross(sub(c, a), r) / denominator
        if 0 <= t <= 1 and 0 <= u <= 1:
            p = (a[0] + t * r[0], a[1] + t * r[1])
            cuts[i].add(p)
            cuts[j].add(p)
    elif cross(sub(c, a), r) == 0:
        for p in (a, b, c, d):
            if on_segment(p, a, b):
                cuts[i].add(p)
            if on_segment(p, c, d):
                cuts[j].add(p)

edges = set()
for (a, b), points in zip(segments, cuts):
    direction = sub(b, a)
    ordered = sorted(points, key=lambda p: dot(sub(p, a), direction))
    for p, q in zip(ordered, ordered[1:]):
        if p != q:
            edges.add(tuple(sorted((p, q))))

vertices = sorted({p for edge in edges for p in edge})
index = {p: i for i, p in enumerate(vertices)}
adjacency = [set() for _ in vertices]
for a, b in edges:
    i, j = index[a], index[b]
    adjacency[i].add(j)
    adjacency[j].add(i)

# Enumerate every simple cycle, once in each unoriented equivalence class.
cycles = set()
for root in range(len(vertices)):
    def visit(path, used):
        for nxt in adjacency[path[-1]]:
            if nxt == root and len(path) >= 3:
                forward = tuple(path)
                backward = (root,) + tuple(reversed(path[1:]))
                cycles.add(min(forward, backward))
            elif nxt > root and nxt not in used:
                visit(path + [nxt], used | {nxt})
    visit([root], {root})

def simplify(polygon):
    polygon = list(polygon)
    while True:
        keep = [
            p for i, p in enumerate(polygon)
            if cross(sub(p, polygon[i - 1]),
                     sub(polygon[(i + 1) % len(polygon)], p)) != 0
        ]
        if len(keep) == len(polygon):
            return polygon
        polygon = keep
        if len(polygon) < 3:
            return []

def strictly_inside(p, polygon):
    inside = False
    for a, b in zip(polygon, polygon[1:] + polygon[:1]):
        if on_segment(p, a, b):
            return False
        if (a[1] > p[1]) != (b[1] > p[1]):
            crossing_x = a[0] + (
                (p[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            )
            if crossing_x > p[0]:
                inside = not inside
    return inside

def has_internal_line(polygon):
    for a, b in edges:
        midpoint = ((a[0] + b[0]) / 2, (a[1] + b[1]) / 2)
        if strictly_inside(midpoint, polygon):
            return True
    return False

# Relative tolerance is used only for metric classification affected by
# coordinates rounded to five decimal places.
TOL = 1e-5

def approximately_zero(value, scale):
    return abs(float(value)) <= TOL * max(float(scale), 1e-20)

def parallel(a, b):
    return approximately_zero(cross(a, b), (dot(a, a) * dot(b, b)) ** F(1, 2))

def perpendicular(a, b):
    return approximately_zero(dot(a, b), (dot(a, a) * dot(b, b)) ** F(1, 2))

def equal_lengths(vectors):
    lengths = [float(dot(v, v)) for v in vectors]
    return max(lengths) - min(lengths) <= TOL * max(lengths)

def regular(vectors):
    if not equal_lengths(vectors):
        return False
    cosines = []
    for a, b in zip(vectors, vectors[1:] + vectors[:1]):
        cosines.append(float(dot(a, b)) /
                       (float(dot(a, a)) * float(dot(b, b))) ** 0.5)
    return max(cosines) - min(cosines) <= TOL

found = {}

def record(number, polygon):
    found.setdefault(number, polygon)

for cycle in sorted(cycles):
    polygon = simplify([vertices[i] for i in cycle])
    n = len(polygon)
    if n < 3:
