    vectors = [
        sub(polygon[(i + 1) % n], polygon[i]) for i in range(n)
    ]
    turns = [cross(vectors[i - 1], vectors[i]) for i in range(n)]
    convex = all(t > 0 for t in turns) or all(t < 0 for t in turns)
    right_angles = [
        perpendicular(vectors[i - 1], vectors[i]) for i in range(n)
    ]

    if n == 3:
