    point = (F(x), F(y))
    if command == "L" and point != previous:
        segments.append((previous, point))
    previous = point

# Split every segment at every intersection, including collinear overlaps.
points = {p for segment in segments for p in segment}
for a, b in segments:
    r = sub(b, a)
    for c, d in segments:
