        current = route[-1]
        for nxt in sorted(graph[current]):
            if nxt == start:
                if len(route) >= 3 and route[1] < route[-1]:
                    cycles.append(tuple(route))
            elif nxt > start and nxt not in used:
                visit(route + [nxt], used | {nxt})
    visit([start], {start})

def corners(cycle):
    polygon = [vertices[i] for i in cycle]
    while True:
        reduced = [
            p for i, p in enumerate(polygon)
            if cross(sub(p, polygon[i-1]),
                     sub(polygon[(i+1) % len(polygon)], p)) != 0
        ]
        if len(reduced) == len(polygon):
            return polygon
        polygon = reduced
        if len(polygon) < 3:
            return []

def inside(p, polygon):
    result = False
    for a, b in zip(polygon, polygon[1:] + polygon[:1]):
        if on_segment(p, a, b):
            return False
        if (a[1] > p[1]) != (b[1] > p[1]):
            x = a[0] + (p[1]-a[1])*(b[0]-a[0])/(b[1]-a[1])
            if x > p[0]:
                result = not result
    return result

def drawn_straight(a, b):
    """Check complete coverage of a candidate straight diagonal."""
    direction = sub(b, a)
    length2 = dot(direction, direction)
    intervals = []
    for c, d in segments:
        if cross(sub(c, a), direction) == cross(sub(d, a), direction) == 0:
            lo, hi = sorted((dot(sub(c, a), direction)/length2,
                             dot(sub(d, a), direction)/length2))
            lo, hi = max(lo, F(0)), min(hi, F(1))
            if lo <= hi:
                intervals.append((lo, hi))
