    return False

# Relative tolerance only for properties affected by coordinate rounding.
tolerance = F(1, 100000)
def nearly_equal(a, b):
    return abs(a-b) <= tolerance * max(abs(a), abs(b), F(1))

def perpendicular(a, b):
    return dot(a, b)**2 <= tolerance**2 * dot(a, a)*dot(b, b)

found = set()
witnesses = {}
for cycle in cycles:
    polygon = corners(cycle)
    n = len(polygon)
    if n < 3:
