    sides = [sub(polygon[(i+1) % n], polygon[i]) for i in range(n)]
    lengths = [dot(v, v) for v in sides]
    turns = [cross(sides[i-1], sides[i]) for i in range(n)]
    convex = all(t > 0 for t in turns) or all(t < 0 for t in turns)
    labels = []

    if n == 3:
        right = any(perpendicular(sides[i-1], sides[i]) for i in range(n))
        labels.append(4 if right else 3)
    elif not has_diagonal(polygon):
        if n == 4:
            parallel_pairs = sum(
                cross(sides[i], sides[i+2]) == 0 for i in range(2)
            )
            right = all(perpendicular(sides[i-1], sides[i]) for i in range(n))
            equal = all(nearly_equal(x, lengths[0]) for x in lengths)
            if parallel_pairs == 2:
                labels.append(2 if right and equal else 1 if right else 5)
            elif convex and parallel_pairs == 1:
                labels.append(6)
        elif n in (5, 6):
            equal_sides = all(nearly_equal(x, lengths[0]) for x in lengths)
            adjacent_dots = [dot(sides[i-1], sides[i]) for i in range(n)]
            equal_angles = all(nearly_equal(x, adjacent_dots[0])
                               for x in adjacent_dots)
            regular = convex and equal_sides and equal_angles
            if n == 5:
                labels.append(9 if regular else 7 if convex else 8)
            elif regular:
                labels.append(10)

    for label in labels:
