    ("Rule10", ("badger_and_shark_initials_match",), "not_badger_trades"),
    ("Rule11", ("vampire_takes_over",), "not_pelikan_hides_cards"),
    ("Rule12", ("gadwall_builds_plant",), "not_gadwall_hugs"),
    ("Rule13", ("mouse_refuses_stork",), "stork_surrenders"),
]
# Rule9 and Rule12 are instantiated for the gadwall, the relevant creature.
preferred = {("Rule13", "Rule2"), ("Rule8", "Rule11"), ("Rule9", "Rule12")}

def opposite(literal):
    return literal[4:] if literal.startswith("not_") else "not_" + literal

state = frozenset(facts)
seen = set()
settled = False

for _ in range(100):
    if state in seen:
        break
    seen.add(state)
    enabled = [(name, premises, conclusion)
               for name, premises, conclusion in rules
               if all(p in state for p in premises)]
    accepted = [
        rule for rule in enabled
        if not any(
            other[2] == opposite(rule[2])
            and (other[0], rule[0]) in preferred
            for other in enabled
        )
    ]
    next_state = frozenset(facts | {r[2] for r in accepted})
    if next_state == state:
        settled = True
        break
    state = next_state

if not settled:
    print("UNSUPPORTED")
else:
    positive = "pelikan_swears" in state
    negative = "not_pelikan_swears" in state
    if positive and negative:
        print("UNSUPPORTED")
    else:
        answer = "proved" if positive else "disproved" if negative else "unknown"
        supporting_rules = {}
        for name, premises, conclusion in accepted:
            supporting_rules.setdefault(conclusion, []).append((name, premises))

        def proof(literal):
            if literal in facts:
                return {"fact": literal}
            name, premises = supporting_rules[literal][0]
            return {
                "literal": literal,
                "rule": name,
                "from": [proof(p) for p in premises],
            }

        evidence = {
            "friends": friends,
            "blue_in_France_flag": "blue" in france_flag_colors,
            "positive_query_derived": positive,
            "negative_query_derived": negative,
        }
        if positive or negative:
            evidence["proof"] = proof(
                "pelikan_swears" if positive else "not_pelikan_swears"
            )
        print(json.dumps(
            {"final_answer": answer, "evidence": evidence},
            separators=(",", ":")
        ))
