import itertools
import json

countries = ("Britain", "Germany", "South Korea", "France")
languages = frozenset(countries)

options = {
    "A": ("Britain", "Germany", "South Korea", "France"),
    "B": ("France", "Britain", "Germany", "South Korea"),
    "C": ("Germany", "Britain", "France", "South Korea"),
    "D": ("Germany", "Britain", "South Korea", "France"),
}

def possible_languages(required):
    optional = sorted(languages - required)
    for mask in range(1 << len(optional)):
        yield required | {
            language for i, language in enumerate(optional)
            if mask & (1 << i)
        }

solutions = []
# Allow unmentioned language skills, rather than assuming they are absent.
for french in possible_languages({"France", "Germany"}):
    for british in possible_languages({"Britain", "South Korea"}):
        spoken = {
            "South Korea": {"South Korea"},
            "France": french,
            "Britain": british,
            "Germany": languages,
        }
        for order in itertools.permutations(countries):
            if order.index("South Korea") <= order.index("Germany"):
                continue

            communicating_neighbors = {}
            for i, country in enumerate(order):
                neighbors = [
                    order[j] for j in (i - 1, i + 1)
                    if 0 <= j < len(order)
                ]
                communicating_neighbors[country] = sum(
                    bool(spoken[country] & spoken[neighbor])
                    for neighbor in neighbors
                )

            if (
                communicating_neighbors["South Korea"] == 0
                and communicating_neighbors["France"] == 0
                and communicating_neighbors["Britain"] == 1
            ):
                solutions.append((order, communicating_neighbors))

orders = sorted({order for order, _ in solutions})
matching_options = [
    label for label, order in options.items()
    if orders == [order]
]

if len(matching_options) == 1:
    label = matching_options[0]
    answer = label + ". " + ", ".join(options[label])
else:
    answer = "UNSUPPORTED"

print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "valid_orders": [list(order) for order in orders],
        "valid_language_and_room_assignments": len(solutions),
        "communicating_neighbor_counts": (
            solutions[0][1] if len(orders) == 1 else None
        )
    }
}, separators=(",", ":")))
